  "CDATA.generations[2].wheels.oem[9].note": "An ET52 version also exists, but it requires the rear arch lip protector",
  "CDATA.generations[2].tyres[0].note": "Official manual, C180 summer (same size front and rear)",
  "CDATA.generations[2].tyres[1].note": "Official manual, C180 summer",
  "CDATA.generations[2].tyres[2].note": "Official manual, C180 summer",
  "CDATA.generations[2].tyres[3].note": "Official manual, mainstream 17-inch (same front and rear, or front)",
  "CDATA.generations[2].tyres[4].note": "Rear of the 17-inch staggered setup",
  "CDATA.generations[2].tyres[5].note": "18-inch front wheel",
  "CDATA.generations[2].tyres[6].note": "18-inch rear wheel",
  "CDATA.generations[2].tyres[7].note": "19-inch front wheel",
  "CDATA.generations[2].tyres[8].note": "19-inch rear wheel; the C63 S AMG Estate also runs this size at the front",
